class BoundedStack(T)
  getter capacity : Int32
  getter size : Int32

  def initialize(@capacity : Int32)
    @storage = Array(T).new(@capacity)
    @size = 0
  end

  def push(element : T) : self
    raise "BoundedStack is full (capacity: #{@capacity})" if full?
    @storage << element
    @size += 1
    self
  end

  def pop : T
    raise "BoundedStack is empty" if empty?
    @size -= 1
    @storage.pop
  end

  def peek : T
    raise "BoundedStack is empty" if empty?
    @storage.last
  end

  def full? : Bool
    @size >= @capacity
  end

  def empty? : Bool
    @size == 0
  end
end

class ConfigStore
  def initialize(fallback_value : String = "")
    @store = Hash(String, String).new(fallback_value)
  end

  def set(key : String, value : String) : Nil
    @store[key] = value
  end

  def get(key : String) : String
    @store[key]
  end

  def fetch_with_fallback(key : String, fallback : String) : String
    @store.fetch(key, fallback)
  end

  def merge_overriding(overrides : Hash(String, String)) : Nil
    @store.merge!(overrides)
  end

  def keys_matching(&predicate : String -> Bool) : Array(String)
    @store.each_with_object([] of String) do |(key, value), list_of_matches|
      list_of_matches << key if predicate.call(value)
    end
  end

  def to_snapshot : Hash(String, String)
    @store.dup
  end
end

