struct PipelineWorker
  def initialize(
    @source : Channel(String),
    @sink : Channel(String)
  )
  end

  def process : Nil
    while (raw_value = @source.receive?)
      @sink.send(raw_value.upcase)
    end
    @sink.close
  end
end

class WorkQueue(T)
  def initialize(worker_count : Int32, &worker_block : T -> Nil)
    @job_channel = Channel(T).new(worker_count * 2)
    @done_channel = Channel(Nil).new(worker_count)

    worker_count.times do
      spawn do
        while (next_job = @job_channel.receive?)
          worker_block.call(next_job)
        end
        @done_channel.send(nil)
      end
    end

    @worker_count = worker_count
  end

  def push(job : T) : Nil
    @job_channel.send(job)
  end

  def drain : Nil
    @job_channel.close
    @worker_count.times { @done_channel.receive }
  end
end

class FanOutDispatcher
  def initialize(
    @source_channel : Channel(Int32),
    @list_of_workers : Array(Channel(Int32))
  )
    @worker_index = 0
  end

  def dispatch : Nil
    while (incoming_value = @source_channel.receive?)
      target_channel = @list_of_workers[@worker_index % @list_of_workers.size]
      target_channel.send(incoming_value)
      @worker_index += 1
    end
    @list_of_workers.each(&.close)
  end
end

class FrequencyCounter
  def initialize(list_of_words : Array(String))
    @frequency_map = Hash(String, Int32).new(0)
    list_of_words.each { |word| @frequency_map[word] += 1 }
  end

  def top(count : Int32) : Array(String)
    sorted_by_frequency.first(count).map(&.first)
  end

  def grouped_by_frequency : Hash(Int32, Array(String))
    @frequency_map.group_by { |_word, freq| freq }.transform_values do |pairs|
      pairs.map(&.first)
    end
  end

  private def sorted_by_frequency : Array(Tuple(String, Int32))
    @frequency_map.to_a.sort_by { |_word, freq| -freq }
  end
end

class BoundedStack(T)
  class StackOverflowError < Exception; end
  class StackUnderflowError < Exception; end

  getter capacity : Int32

  def initialize(@capacity : Int32)
    @storage = Array(T).new(@capacity)
  end

  def push(element : T) : self
    raise StackOverflowError.new("Stack is full (capacity: #{@capacity})") if is_full?
    @storage.push(element)
    self
  end

  def pop : T
    raise StackUnderflowError.new("Cannot pop from an empty stack") if is_empty?
    @storage.pop
  end

  def peek : T
    raise StackUnderflowError.new("Cannot peek an empty stack") if is_empty?
    @storage.last
  end

  def is_full? : Bool
    @storage.size >= @capacity
  end

  def is_empty? : Bool
    @storage.empty?
  end

  def size : Int32
    @storage.size
  end
end

class LruCache(K, V)
  def initialize(@max_size : Int32)
    @storage = Hash(K, V).new
    @access_order = Array(K).new
  end

  def get(key : K) : V?
    return nil unless @storage.has_key?(key)
    promote(key)
    @storage[key]
  end

  def put(key : K, value : V) : Nil
    if @storage.has_key?(key)
      @storage[key] = value
      promote(key)
    else
      evict_oldest if @storage.size >= @max_size
      @storage[key] = value
      @access_order.push(key)
    end
  end

  def has_key?(key : K) : Bool
    @storage.has_key?(key)
  end

  def size : Int32
    @storage.size
  end

  private def promote(key : K) : Nil
    @access_order.delete(key)
    @access_order.push(key)
  end

  private def evict_oldest : Nil
    oldest_key = @access_order.shift
    @storage.delete(oldest_key)
  end
end

class InventoryLedger
  def initialize
    @stock_levels = Hash(String, Int32).new(0)
  end

  def apply_adjustment(sku : String, signed_delta : Int32) : Nil
    @stock_levels[sku] += signed_delta
  end

