class SlidingWindowAggregator
  def initialize(@window_size : Int32)
    @collection_of_samples = Array(Float64).new
  end

  def push(sample : Float64) : Nil
    @collection_of_samples.push(sample)
    @collection_of_samples.shift if @collection_of_samples.size > @window_size
  end

  def mean : Float64
    return 0.0 if @collection_of_samples.empty?
    @collection_of_samples.sum / @collection_of_samples.size
  end

  def minimum : Float64?
    @collection_of_samples.min?
  end

  def maximum : Float64?
    @collection_of_samples.max?
  end

  def is_full? : Bool
    @collection_of_samples.size >= @window_size
  end

  def sample_count : Int32
    @collection_of_samples.size
  end
end

