class KeyValueConfig
  def initialize(source : String)
    @map_of_entries = {} of String => String
    source.each_line do |raw_line|
      line = raw_line.strip
      next if line.empty? || line.starts_with?('#')
      if match = /\A([\w.-]+)\s*=\s*(.*?)\z/.match(line)
        key = match[1].strip
        value = match[2].strip
        @map_of_entries[key] = value
      end
    end
  end

  def get(key : String) : String?
    @map_of_entries[key]?
  end

  def keys : Array(String)
    @map_of_entries.keys
  end

  def has_key?(key : String) : Bool
    @map_of_entries.has_key?(key)
  end

  def size : Int32
    @map_of_entries.size
  end
end

