class ProductCatalogEntry
  include JSON::Serializable

  property product_name : String
  property sku : String
  property price_cents : Int64
  property discount_percentage : Float64?
  property list_of_tags : Array(String)

  def initialize(
    @product_name : String,
    @sku : String,
    @price_cents : Int64,
    @discount_percentage : Float64? = nil,
    @list_of_tags : Array(String) = [] of String
  )
  end

  def discounted_price_cents : Int64
    multiplier = discount_percentage.try { |pct| 1.0 - (pct / 100.0) } || 1.0
    (price_cents * multiplier).round.to_i64
  end
end
